effect.shader:
const float PI = 3.14159265;

float getMatte(vec4 col) {
    float mv;
    if (matteUse == 1) {
        mv = dot(col.rgb, vec3(0.299, 0.587, 0.114));
    } else {
        mv = col.a;
    }
    if (invertMatte == 1) mv = 1.0 - mv;
    return clamp(mv, 0.0, 1.0);
}

// Incremental Gaussian blur — same algorithm as the reference gaussianblur effect
vec4 gaussianBlur(sampler2D tex, vec2 uv, vec2 texOffset, float kernelSize) {
    if (kernelSize <= 0.0) return texture2DCv(tex, uv);

    float adjSigma = kernelSize / 2.14596602;

    vec3 ig;
    ig.x = 1.0 / (sqrt(2.0 * PI) * adjSigma);
    ig.y = exp(-0.5 / (adjSigma * adjSigma));
    ig.z = ig.y * ig.y;

    vec4 avgValue = texture2DCv(tex, uv) * ig.x;
    float coeffSum = ig.x;

    for (float i = 1.0; i <= kernelSize; i += 2.0) {
        float offset0 = i;
        float offset1 = i + 1.0;

        ig.xy *= ig.yz;
        coeffSum += 2.0 * ig.x;
        float w0 = ig.x;

        ig.xy *= ig.yz;
        coeffSum += 2.0 * ig.x;
        float w1 = ig.x;

        float wL = w0 + w1;
        float oL = (offset0 * w0 + offset1 * w1) / wL;

        avgValue += texture2DCv(tex, uv - oL * texOffset) * wL;
        avgValue += texture2DCv(tex, uv + oL * texOffset) * wL;
    }

    return avgValue / coeffSum;
}

// ==========================================
// PASS 0 — downsample matte at offset position
// ==========================================
void pass0() {
    vec2 uv = acScreenNorm - vec2(shiftX, shiftY);
    vec4 src = texture2DCv(inputImg.texture, uv);
    float m = getMatte(src);
    gl_FragColor = vec4(m, m, m, m);
}

// ==========================================
// PASS 1 — horizontal Gaussian blur
// ==========================================
void pass1() {
    vec2 uv = acScreenNorm;
    float kernelSize = shadowBlur / 2.0 * 1.14 / 4.0 / 3.0 * length(acPreviewSize);
    vec2 texOffset = vec2(1.0 / bufferA.size.x, 0.0);
    gl_FragColor = gaussianBlur(bufferA.texture, uv, texOffset, kernelSize);
}

// ==========================================
// PASS 2 — vertical Gaussian blur
// ==========================================
void pass2() {
    vec2 uv = acScreenNorm;
    float kernelSize = shadowBlur / 2.0 * 1.14 / 4.0 / 3.0 * length(acPreviewSize);
    vec2 texOffset = vec2(0.0, 1.0 / bufferB.size.y);
    gl_FragColor = gaussianBlur(bufferB.texture, uv, texOffset, kernelSize);
}

// ==========================================
// PASS 3 — composite shadow + foreground
// ==========================================
void pass3() {
    vec2 uv = acScreenNorm;

    float blurredMatte = texture2DCv(bufferC.texture, uv).r;
    float shadowMatte = clamp(blurredMatte * shadowOpacity, 0.0, 1.0);

    // Shadow
    vec4 shadow = vec4(shadowColor.rgb * shadowMatte, shadowMatte);

    // Foreground
    vec4 fg = texture2DCv(inputImg.texture, uv);
    float fgA = getMatte(fg) * fgOpacity;

    // Composite fg over shadow
    vec3 rgb = shadow.rgb * (1.0 - fgA) + fg.rgb * fgA;
    float a   = shadow.a + fgA * (1.0 - shadow.a);

    gl_FragColor = vec4(rgb, a);
}

void main() {
    if (acPass == 0) {
        pass0();
    } else if (acPass == 1) {
        pass1();
    } else if (acPass == 2) {
        pass2();
    } else {
        pass3();
    }
}
